package com.ds.goroute.controller;
import com.ds.goroute.dto.BaseResponse;import com.ds.goroute.dto.request.*;import com.ds.goroute.dto.response.*;import com.ds.goroute.service.MarketplaceChatService;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;import org.springframework.http.*;import org.springframework.security.authentication.AuthenticationCredentialsNotFoundException;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/v1/api/marketplace-chat") @RequiredArgsConstructor
public class MarketplaceChatController {private final MarketplaceChatService s;@PostMapping("/conversations")public ResponseEntity<BaseResponse<MarketplaceConversationResponse>> start(Authentication a,@Valid @RequestBody StartMarketplaceConversationRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(BaseResponse.ofSucceeded(s.start(user(a),r)));}@GetMapping("/conversations")public ResponseEntity<BaseResponse<List<MarketplaceConversationResponse>>> list(Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="30")int size){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.listMine(user(a),page,size)));}@GetMapping("/conversations/{id}")public ResponseEntity<BaseResponse<MarketplaceConversationResponse>> get(Authentication a,@PathVariable UUID id){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.get(user(a),id)));}@GetMapping("/conversations/{id}/messages")public ResponseEntity<BaseResponse<List<MarketplaceMessageResponse>>> messages(Authentication a,@PathVariable UUID id,@RequestParam(required=false)Long afterSequence,@RequestParam(defaultValue="100")int limit){return ResponseEntity.ok(BaseResponse.ofSucceeded(s.messages(user(a),id,afterSequence,limit)));}@PostMapping("/conversations/{id}/messages")public ResponseEntity<BaseResponse<MarketplaceMessageResponse>> send(Authentication a,@PathVariable UUID id,@Valid @RequestBody SendMarketplaceMessageRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(BaseResponse.ofSucceeded(s.send(user(a),id,r)));}@PostMapping("/conversations/{id}/read/{messageId}")public ResponseEntity<BaseResponse<Void>> read(Authentication a,@PathVariable UUID id,@PathVariable UUID messageId){s.markRead(user(a),id,messageId);return ResponseEntity.ok(BaseResponse.ofSucceeded());}private UUID user(Authentication a){if(a==null||a.getPrincipal()==null)throw new AuthenticationCredentialsNotFoundException("Authentication required");Object p=a.getPrincipal();return p instanceof UUID id?id:UUID.fromString(p.toString());}}
